-- Additive SUAS workflows. Historical tables and records are preserved.
CREATE TABLE "SocialPocDataset" (id TEXT PRIMARY KEY, "referenceDate" DATE NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialUnitRegistration" ("unitId" TEXT PRIMARY KEY REFERENCES "SocialUnit"(id), cnpj TEXT, "legalName" TEXT NOT NULL, "stateRegistration" TEXT, "unitNumber" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialProfessionalRegistration" ("employeeId" TEXT PRIMARY KEY REFERENCES "Employee"(id), "roleId" TEXT REFERENCES "Role"(id), council TEXT, registration TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialBeneficiaryRegistration" ("personId" TEXT PRIMARY KEY REFERENCES "Person"(id), "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), religion TEXT, "birthCertificate" TEXT, "registeredAt" DATE NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialBenefitClassification" ("benefitId" TEXT PRIMARY KEY REFERENCES "SocialBenefit"(id), sphere TEXT NOT NULL CHECK (sphere IN ('Federal','Estadual','Municipal')), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialFamilyRegistration" ("familyId" TEXT PRIMARY KEY REFERENCES "SocialFamily"(id), "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialProgramEnrollment" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "familyId" TEXT REFERENCES "SocialFamily"(id), "personId" TEXT REFERENCES "Person"(id), "programId" TEXT NOT NULL REFERENCES "SocialProgram"(id), "registeredAt" DATE NOT NULL, "includedAt" DATE NOT NULL, "excludedAt" DATE, "benefitValue" NUMERIC(14,2) NOT NULL CHECK ("benefitValue">=0), "benefitNumber" TEXT, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (("familyId" IS NULL) <> ("personId" IS NULL)), CHECK ("excludedAt" IS NULL OR "excludedAt">="includedAt"));
CREATE INDEX "SocialProgramEnrollment_subject_idx" ON "SocialProgramEnrollment"("familyId","personId");
CREATE TABLE "SocialRequestDetails" ("requestId" TEXT PRIMARY KEY REFERENCES "SocialBenefitRequest"(id), "professionalId" TEXT NOT NULL REFERENCES "Employee"(id), "requestedAt" DATE NOT NULL, "applicantId" TEXT NOT NULL REFERENCES "Person"(id), "recipientId" TEXT NOT NULL REFERENCES "Person"(id), "deliveryType" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialReferralDetails" ("referralId" TEXT PRIMARY KEY REFERENCES "SocialReferral"(id), "professionalId" TEXT NOT NULL REFERENCES "Employee"(id), "referralType" TEXT NOT NULL, "destinationUnitId" TEXT REFERENCES "SocialUnit"(id), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialFollowup" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "familyId" TEXT REFERENCES "SocialFamily"(id), "personId" TEXT REFERENCES "Person"(id), "professionalId" TEXT NOT NULL REFERENCES "Employee"(id), service TEXT NOT NULL, "startsAt" DATE NOT NULL, "endsAt" DATE, diagnosis TEXT NOT NULL, objectives TEXT NOT NULL, actions TEXT NOT NULL, "reviewAt" DATE, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','CLOSED')), "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (("familyId" IS NULL) <> ("personId" IS NULL)), CHECK ("endsAt" IS NULL OR "endsAt">="startsAt"));
CREATE INDEX "SocialFollowup_unit_dates_idx" ON "SocialFollowup"("unitId","startsAt","endsAt");
CREATE TABLE "SocialFollowupNote" (id TEXT PRIMARY KEY, "followupId" TEXT NOT NULL REFERENCES "SocialFollowup"(id), "occurredAt" DATE NOT NULL, description TEXT NOT NULL, "nextReviewAt" DATE, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialConditionality" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "personId" TEXT NOT NULL REFERENCES "Person"(id), "programId" TEXT NOT NULL REFERENCES "SocialProgram"(id), kind TEXT NOT NULL, "dueAt" DATE NOT NULL, "occurredAt" DATE, effect TEXT NOT NULL, "suspensionFrom" DATE, "suspensionUntil" DATE, status TEXT NOT NULL CHECK (status IN ('PENDING','COMPLIED','NONCOMPLIANCE','SUSPENDED')), observations TEXT NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK ("suspensionUntil" IS NULL OR "suspensionUntil">="suspensionFrom"));
CREATE TABLE "SocialQuestionnaire" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), title TEXT NOT NULL, version INTEGER NOT NULL CHECK (version>0), "previousId" TEXT REFERENCES "SocialQuestionnaire"(id), questions JSONB NOT NULL CHECK (jsonb_typeof(questions)='array'), "isActive" BOOLEAN NOT NULL DEFAULT true, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialQuestionnaireResponse" (id TEXT PRIMARY KEY, "questionnaireId" TEXT NOT NULL REFERENCES "SocialQuestionnaire"(id), "familyId" TEXT REFERENCES "SocialFamily"(id), "personId" TEXT REFERENCES "Person"(id), "answeredAt" DATE NOT NULL, answers JSONB NOT NULL CHECK (jsonb_typeof(answers)='object'), "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (("familyId" IS NULL) <> ("personId" IS NULL)));
CREATE TABLE "SocialScfvGroup" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "realizationUnitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), name TEXT NOT NULL, "serviceType" TEXT NOT NULL, "ageMin" INTEGER NOT NULL CHECK ("ageMin">=0), "ageMax" INTEGER NOT NULL CHECK ("ageMax">="ageMin"), "registeredAt" DATE NOT NULL, "startsAt" DATE NOT NULL, "endsAt" DATE NOT NULL CHECK ("endsAt">="startsAt"), "professionalId" TEXT NOT NULL REFERENCES "Employee"(id), "referenceProfessionalId" TEXT NOT NULL REFERENCES "Employee"(id), "advisorId" TEXT NOT NULL REFERENCES "Employee"(id), "facilitatorId" TEXT NOT NULL REFERENCES "Employee"(id), weekdays INTEGER[] NOT NULL, "startTime" TEXT NOT NULL, "endTime" TEXT NOT NULL CHECK ("endTime">"startTime"), "isActive" BOOLEAN NOT NULL DEFAULT true, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialScfvEnrollment" (id TEXT PRIMARY KEY, "groupId" TEXT NOT NULL REFERENCES "SocialScfvGroup"(id), "personId" TEXT NOT NULL REFERENCES "Person"(id), "enrolledAt" DATE NOT NULL, "leftAt" DATE CHECK ("leftAt" IS NULL OR "leftAt">="enrolledAt"), "exitReason" TEXT, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SocialScfvEnrollment_group_person_idx" ON "SocialScfvEnrollment"("groupId","personId");
CREATE UNIQUE INDEX "SocialScfvEnrollment_active_key" ON "SocialScfvEnrollment"("groupId","personId") WHERE "leftAt" IS NULL;
CREATE TABLE "SocialScfvEvent" (id TEXT PRIMARY KEY, "groupId" TEXT NOT NULL REFERENCES "SocialScfvGroup"(id), title TEXT NOT NULL, "occursAt" DATE NOT NULL, planning TEXT NOT NULL, report TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','REALIZED','CANCELLED')), "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialScfvAttendance" (id TEXT PRIMARY KEY, "eventId" TEXT NOT NULL REFERENCES "SocialScfvEvent"(id), "enrollmentId" TEXT NOT NULL REFERENCES "SocialScfvEnrollment"(id), present BOOLEAN NOT NULL, justification TEXT, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("eventId","enrollmentId"));
CREATE TABLE "SocialAttachment" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "eventId" TEXT REFERENCES "SocialScfvEvent"(id), "personId" TEXT REFERENCES "Person"(id), "documentId" TEXT NOT NULL REFERENCES "Document"(id), caption TEXT NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (("eventId" IS NULL) <> ("personId" IS NULL)));
CREATE TABLE "SocialMessage" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "personId" TEXT NOT NULL REFERENCES "Person"(id), "programEnrollmentId" TEXT NOT NULL REFERENCES "SocialProgramEnrollment"(id), phone TEXT NOT NULL, body TEXT NOT NULL, "dueAt" DATE NOT NULL, status TEXT NOT NULL DEFAULT 'AWAITING_PROVIDER', "dedupeKey" TEXT NOT NULL, "externalId" TEXT, "lastError" TEXT, "sentAt" TIMESTAMP(3), "deliveredAt" TIMESTAMP(3), "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialMessage_dedupe_key" ON "SocialMessage"("dedupeKey");
CREATE TABLE "SocialImportBatch" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), filename TEXT NOT NULL, sha256 TEXT NOT NULL, layout TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PREVIEW' CHECK (status IN ('PREVIEW','APPLIED')), accepted INTEGER NOT NULL CHECK (accepted>=0), rejected INTEGER NOT NULL CHECK (rejected>=0), "createdBy" TEXT NOT NULL, "appliedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialImportBatch_unit_hash_layout_key" ON "SocialImportBatch"("unitId",sha256,layout);
CREATE TABLE "SocialImportRow" (id TEXT PRIMARY KEY, "batchId" TEXT NOT NULL REFERENCES "SocialImportBatch"(id), line INTEGER NOT NULL, payload JSONB NOT NULL, "personId" TEXT REFERENCES "Person"(id), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialImportRow_batch_line_key" ON "SocialImportRow"("batchId",line);
INSERT INTO "DocumentClass" (id,code,label,"signaturePolicy","isActive","updatedAt") VALUES ('social-suas-evidence','SOCIAL_EVIDENCE','Documentação socioassistencial','INTERNAL_ALLOWED',true,CURRENT_TIMESTAMP) ON CONFLICT (code) DO NOTHING;
